input.new_string:
const { trim, capitalize } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('capitalize', () => {
  assert.strictEqual(capitalize('abc'), 'Abc');
  assert.strictEqual(capitalize('Abc'), 'Abc');
  assert.strictEqual(capitalize(''), '');
});

function reverse(s) {
  return [...s].reverse().join('');
}

module.exports = { trim, capitalize, reverse };

test('capitalize', () => {
  assert.strictEqual(capitalize('abc'), 'Abc');
  assert.strictEqual(capitalize('Abc'), 'Abc');
  assert.strictEqual(capitalize(''), '');
});

test('reverse', () => {
  assert.strictEqual(reverse('abc'), 'cba');
  assert.strictEqual(reverse('a'), 'a');
  assert.strictEqual(reverse(''), '');
});

function countWords(s) {
  const t = trim(s);
  if (t.length === 0) return 0;
  return t.split(/\s+/).length;
}

module.exports = { trim, capitalize, reverse, countWords };

test('reverse', () => {
  assert.strictEqual(reverse('abc'), 'cba');
  assert.strictEqual(reverse('a'), 'a');
  assert.strictEqual(reverse(''), '');
});

test('countWords', () => {
  assert.strictEqual(countWords('a b c'), 3);
  assert.strictEqual(countWords('  a   b  '), 2);
  assert.strictEqual(countWords('a\nb\tc'), 3);
  assert.strictEqual(countWords('one'), 1);
  assert.strictEqual(countWords(''), 0);
  assert.strictEqual(countWords('   '), 0);
});

